// Dynamic item pool on top of the authored seed bank.
//
// Lifecycle of a generated item (see docs/dynamic_bank.md):
//   generated by an LLM from a seed family -> local checks -> independent solver
//   check by a second model -> 'pilot' (shown unscored, one per attempt) ->
//   'active' after expert approval or statistical calibration -> 'retired' on
//   overexposure or drift. Seed items are authored and always scored.
//
// The pool changes WHICH equivalent items a candidate sees, never the blueprint:
// topics, difficulty slots, item count and pass threshold stay fixed per grade.
import { createHash, randomInt, randomUUID } from 'node:crypto';

export const PILOT_MIN_RESPONSES = 12;
export const GENERATED_MAX_EXPOSURES = 150;
export const DRIFT_MIN_RESPONSES = 40;
/** Expected share of correct answers among confirmed-level candidates; used until seed data accumulates. */
export const DIFFICULTY_PRIOR = Object.freeze({ 1: 0.72, 2: 0.55 });
const statuses = ['pilot', 'active', 'rejected', 'retired'];

export const normalizeText = value => String(value).toLocaleLowerCase('ru').replace(/ё/gu, 'е').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
export function itemFingerprint(text, options) {
  return createHash('sha256').update(normalizeText(text) + '\n' + options.map(normalizeText).sort().join('\n')).digest('hex');
}
function tokens(value) {
  return new Set(normalizeText(value).split(' ').filter(word => word.length >= 4).map(word => word.slice(0, 6)));
}
/** Jaccard similarity of stemmed word sets; a cheap guard against paraphrased duplicates. */
export function textSimilarity(a, b) {
  const left = tokens(a), right = tokens(b);
  if (!left.size || !right.size) return 0;
  let shared = 0;
  for (const word of left) if (right.has(word)) shared++;
  return shared / (left.size + right.size - shared);
}

/** Point-biserial correlation of item correctness with the attempt score. */
export function pointBiserial({ responses, correct, scoreSum, scoreCorrectSum, scoreSquareSum }) {
  if (responses < 2 || correct === 0 || correct === responses) return null;
  const mean = scoreSum / responses;
  const variance = scoreSquareSum / responses - mean * mean;
  if (variance <= 1e-9) return null;
  const p = correct / responses;
  const meanCorrect = scoreCorrectSum / correct;
  const meanWrong = (scoreSum - scoreCorrectSum) / (responses - correct);
  return (meanCorrect - meanWrong) / Math.sqrt(variance) * Math.sqrt(p * (1 - p));
}

function weightedPick(items, weight) {
  const total = items.reduce((sum, item) => sum + weight(item), 0);
  let ticket = randomInt(1_000_000) / 1_000_000 * total;
  for (const item of items) {
    ticket -= weight(item);
    if (ticket <= 0) return item;
  }
  return items[items.length - 1];
}

export class ItemBank {
  constructor(db, { programs, now = Date.now } = {}) {
    this.db = db; this.programs = programs; this.now = now;
    db.exec(`
      CREATE TABLE IF NOT EXISTS bank_items (
        id TEXT PRIMARY KEY, family_id TEXT NOT NULL, specialization TEXT NOT NULL, grade TEXT NOT NULL,
        topic TEXT NOT NULL, difficulty INTEGER NOT NULL CHECK(difficulty IN (1,2)), skills TEXT NOT NULL,
        text TEXT NOT NULL, options TEXT NOT NULL, correct INTEGER NOT NULL CHECK(correct BETWEEN 0 AND 3),
        explanation TEXT NOT NULL DEFAULT '', derived_from TEXT,
        status TEXT NOT NULL CHECK(status IN ('pilot','active','rejected','retired')),
        fingerprint TEXT NOT NULL UNIQUE, generator TEXT NOT NULL, verifier TEXT,
        review TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL
      ) STRICT;
      CREATE INDEX IF NOT EXISTS bank_items_family ON bank_items(family_id, status);
      CREATE INDEX IF NOT EXISTS bank_items_program ON bank_items(specialization, grade, status);
      CREATE TABLE IF NOT EXISTS item_stats (
        item_id TEXT PRIMARY KEY, exposures INTEGER NOT NULL DEFAULT 0, responses INTEGER NOT NULL DEFAULT 0,
        correct INTEGER NOT NULL DEFAULT 0, total_ms INTEGER NOT NULL DEFAULT 0,
        score_sum REAL NOT NULL DEFAULT 0, score_correct_sum REAL NOT NULL DEFAULT 0, score_square_sum REAL NOT NULL DEFAULT 0,
        last_used_at TEXT
      ) STRICT;
      CREATE TABLE IF NOT EXISTS item_generation_log (
        id TEXT PRIMARY KEY, family_id TEXT NOT NULL, outcome TEXT NOT NULL, reason TEXT NOT NULL,
        model TEXT NOT NULL, created_at TEXT NOT NULL
      ) STRICT;
      CREATE INDEX IF NOT EXISTS item_generation_log_time ON item_generation_log(created_at);
    `);
    this.families = new Map();
    for (const [specialization, grades] of Object.entries(programs || {})) {
      for (const [grade, program] of Object.entries(grades)) {
        for (const family of program.families) this.families.set(family.id, { ...family, specialization, grade });
      }
    }
  }

  family(id) { return this.families.get(id) || null; }

  timestamp() { return new Date(this.now()).toISOString(); }

  stats(itemId) {
    return this.db.prepare('SELECT * FROM item_stats WHERE item_id=?').get(itemId)
      || { item_id: itemId, exposures: 0, responses: 0, correct: 0, total_ms: 0, score_sum: 0, score_correct_sum: 0, score_square_sum: 0, last_used_at: null };
  }

  row(id) {
    const row = this.db.prepare('SELECT * FROM bank_items WHERE id=?').get(id);
    return row ? this.fromRow(row) : null;
  }

  fromRow(row) {
    return { id: row.id, familyId: row.family_id, specialization: row.specialization, grade: row.grade, topic: row.topic,
      difficulty: row.difficulty, skills: JSON.parse(row.skills), text: row.text, options: JSON.parse(row.options),
      correct: row.correct, explanation: row.explanation, derivedFrom: row.derived_from, status: row.status,
      generator: row.generator, verifier: row.verifier, review: JSON.parse(row.review), origin: 'generated',
      createdAt: row.created_at, updatedAt: row.updated_at };
  }

  /** Seed variants plus active generated clones of the same item model. */
  scoredVariants(family) {
    const generated = this.db.prepare("SELECT * FROM bank_items WHERE family_id=? AND status='active'").all(family.id).map(row => this.fromRow(row));
    return [...family.variants.map(variant => ({ ...variant, origin: 'seed' })), ...generated];
  }

  /**
   * Chooses `count` scored items for one family. Vacancy relevance forms tiers;
   * inside a tier, less exposed items are more likely. Items seen by this owner
   * are used only when no fresh item remains.
   */
  pick(family, count, { seen = new Set(), relevance = () => 0 } = {}) {
    const pool = this.scoredVariants(family);
    const fresh = pool.filter(item => !seen.has(item.id));
    const chosen = [];
    const take = candidates => {
      let remaining = candidates.filter(item => !chosen.includes(item)
        && !chosen.some(other => other.id === item.derivedFrom || item.id === other.derivedFrom));
      while (chosen.length < count && remaining.length) {
        const best = Math.max(...remaining.map(relevance));
        const tier = remaining.filter(item => relevance(item) === best);
        const item = weightedPick(tier, candidate => 1 / (1 + this.stats(candidate.id).exposures / 10));
        chosen.push(item);
        remaining = remaining.filter(other => other !== item && other.id !== item.derivedFrom && other.derivedFrom !== item.id);
      }
    };
    take(fresh);
    if (chosen.length < count) take(pool);
    return chosen;
  }

  /** One unscored generated item per attempt: it collects calibration data, never affects the grade. */
  pilot(specialization, grade, seen = new Set()) {
    const rows = this.db.prepare(`SELECT b.*, COALESCE(s.responses,0) AS responses FROM bank_items b
      LEFT JOIN item_stats s ON s.item_id=b.id WHERE b.specialization=? AND b.grade=? AND b.status='pilot'
      ORDER BY responses, b.created_at LIMIT 20`).all(specialization, grade).filter(row => !seen.has(row.id));
    if (!rows.length) return null;
    const least = rows[0].responses;
    const candidates = rows.filter(row => row.responses <= least + 2);
    return this.fromRow(candidates[randomInt(candidates.length)]);
  }

  recordExposure(itemIds) {
    const time = this.timestamp();
    const statement = this.db.prepare(`INSERT INTO item_stats(item_id,exposures,last_used_at) VALUES(?,1,?)
      ON CONFLICT(item_id) DO UPDATE SET exposures=exposures+1,last_used_at=excluded.last_used_at`);
    for (const id of itemIds) statement.run(id, time);
    this.retireOverexposed(itemIds);
  }

  /** Records answers of a completed attempt and re-evaluates affected generated items. */
  recordResponses(responses, attemptScore) {
    const score = Number(attemptScore) / 100;
    const statement = this.db.prepare(`INSERT INTO item_stats(item_id,responses,correct,total_ms,score_sum,score_correct_sum,score_square_sum)
      VALUES(?,1,?,?,?,?,?) ON CONFLICT(item_id) DO UPDATE SET responses=responses+1,correct=correct+excluded.correct,
      total_ms=total_ms+excluded.total_ms,score_sum=score_sum+excluded.score_sum,
      score_correct_sum=score_correct_sum+excluded.score_correct_sum,score_square_sum=score_square_sum+excluded.score_square_sum`);
    for (const response of responses) {
      const correct = response.correct ? 1 : 0;
      statement.run(response.itemId, correct, Math.max(0, Math.round(response.ms || 0)), score, correct ? score : 0, score * score);
    }
    for (const response of responses) this.calibrate(response.itemId);
  }

  /** Reference share of correct answers for the family: seed data when available, otherwise a prior. */
  referenceDifficulty(family) {
    const rows = family.variants.map(variant => this.stats(variant.id)).filter(row => row.responses >= PILOT_MIN_RESPONSES);
    if (!rows.length) return DIFFICULTY_PRIOR[family.difficulty] ?? 0.65;
    const responses = rows.reduce((sum, row) => sum + row.responses, 0);
    return rows.reduce((sum, row) => sum + row.correct, 0) / responses;
  }

  /**
   * Pilot -> active when its observed difficulty stays within the family band and it
   * discriminates non-negatively. Active generated items with clearly negative
   * discrimination are retired (drift control).
   */
  calibrate(itemId) {
    const item = this.row(itemId);
    if (!item || !['pilot', 'active'].includes(item.status)) return null;
    const stats = this.stats(itemId);
    const family = this.family(item.familyId);
    if (!family) return null;
    const reference = this.referenceDifficulty(family);
    const p = stats.responses ? stats.correct / stats.responses : null;
    const rpb = pointBiserial({ responses: stats.responses, correct: stats.correct, scoreSum: stats.score_sum,
      scoreCorrectSum: stats.score_correct_sum, scoreSquareSum: stats.score_square_sum });
    const calibration = { responses: stats.responses, p, reference, pointBiserial: rpb, checkedAt: this.timestamp() };
    if (item.status === 'pilot' && stats.responses >= PILOT_MIN_RESPONSES) {
      const fits = p !== null && p >= 0.1 && p <= 0.97 && Math.abs(p - reference) <= 0.25 && (rpb === null || rpb >= 0);
      this.setStatus(itemId, fits ? 'active' : 'retired', { calibration, decidedBy: 'statistics',
        reason: fits ? 'Сложность в пределах семейства, дискриминация неотрицательна.' : 'Сложность или дискриминация вне допустимых границ.' });
      return fits ? 'active' : 'retired';
    }
    if (item.status === 'active' && stats.responses >= DRIFT_MIN_RESPONSES && rpb !== null && rpb < -0.05) {
      this.setStatus(itemId, 'retired', { calibration, decidedBy: 'statistics', reason: 'Отрицательная дискриминация: сильные кандидаты ошибаются чаще.' });
      return 'retired';
    }
    return item.status;
  }

  retireOverexposed(itemIds) {
    const placeholders = itemIds.map(() => '?').join(',');
    if (!placeholders) return;
    const rows = this.db.prepare(`SELECT b.id FROM bank_items b JOIN item_stats s ON s.item_id=b.id
      WHERE b.id IN (${placeholders}) AND b.status='active' AND s.exposures>=?`).all(...itemIds, GENERATED_MAX_EXPOSURES);
    for (const row of rows) this.setStatus(row.id, 'retired', { decidedBy: 'exposure', reason: 'Превышен лимит показов: задание могло разойтись.' });
  }

  setStatus(id, status, review = {}) {
    if (!statuses.includes(status)) throw new RangeError('Unknown item status');
    const current = this.row(id);
    if (!current) return false;
    const merged = { ...current.review, ...review, history: [...(current.review.history || []), { status, at: this.timestamp(), by: review.decidedBy || 'system' }] };
    return this.db.prepare('UPDATE bank_items SET status=?,review=?,updated_at=? WHERE id=?')
      .run(status, JSON.stringify(merged), this.timestamp(), id).changes === 1;
  }

  /** Stores a verified generated item as a pilot. Returns null for duplicates. */
  addGenerated(family, item, { generator, verifier, verification }) {
    const fingerprint = itemFingerprint(item.text, item.options);
    if (this.db.prepare('SELECT 1 FROM bank_items WHERE fingerprint=?').get(fingerprint)) return null;
    const id = 'gen-' + randomUUID();
    const time = this.timestamp();
    this.db.prepare(`INSERT INTO bank_items(id,family_id,specialization,grade,topic,difficulty,skills,text,options,correct,explanation,
      derived_from,status,fingerprint,generator,verifier,review,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'pilot',?,?,?,?,?,?)`)
      .run(id, family.id, family.specialization, family.grade, family.topic, family.difficulty, JSON.stringify(item.skills),
        item.text, JSON.stringify(item.options), item.correct, item.explanation || '', item.derivedFrom || null,
        fingerprint, generator, verifier || null, JSON.stringify({ verification, history: [{ status: 'pilot', at: time, by: 'generator' }] }), time, time);
    return this.row(id);
  }

  /** Texts already in the family (seed and stored generated) for duplicate checks. */
  familyTexts(familyId) {
    const family = this.family(familyId);
    const seed = family ? family.variants.map(variant => variant.text) : [];
    const generated = this.db.prepare("SELECT text FROM bank_items WHERE family_id=? AND status IN ('pilot','active','retired')").all(familyId).map(row => row.text);
    return [...seed, ...generated];
  }

  /** Question and keyed answer of the family's live items, for the solver's paraphrase check. */
  familyReferences(familyId, limit = 12) {
    const family = this.family(familyId);
    const seed = family ? family.variants.map(variant => ({ text: variant.text, answer: variant.options[variant.correct] })) : [];
    const generated = this.db.prepare("SELECT text, options, correct FROM bank_items WHERE family_id=? AND status IN ('pilot','active') ORDER BY created_at DESC LIMIT ?")
      .all(familyId, limit).map(row => ({ text: row.text, answer: JSON.parse(row.options)[row.correct] }));
    return [...seed, ...generated];
  }

  log(familyId, outcome, reason, model) {
    this.db.prepare('INSERT INTO item_generation_log VALUES(?,?,?,?,?,?)').run(randomUUID(), familyId, outcome, String(reason).slice(0, 500), model, this.timestamp());
  }

  /** Number of items a candidate could still receive without repeats, per family. */
  freshCapacity(familyId) {
    const family = this.family(familyId);
    if (!family) return 0;
    const seedFresh = family.variants.filter(variant => this.stats(variant.id).exposures < GENERATED_MAX_EXPOSURES).length;
    const generated = this.db.prepare("SELECT COUNT(*) AS n FROM bank_items WHERE family_id=? AND status IN ('pilot','active')").get(familyId).n;
    return seedFresh + generated;
  }

  list({ specialization, grade, status } = {}) {
    const where = [], values = [];
    if (specialization) { where.push('specialization=?'); values.push(specialization); }
    if (grade) { where.push('grade=?'); values.push(grade); }
    if (status) { where.push('status=?'); values.push(status); }
    return this.db.prepare(`SELECT * FROM bank_items ${where.length ? 'WHERE ' + where.join(' AND ') : ''} ORDER BY created_at DESC LIMIT 200`)
      .all(...values).map(row => ({ ...this.fromRow(row), stats: this.stats(row.id) }));
  }

  summary(specialization, grade) {
    const counts = Object.fromEntries(statuses.map(status => [status, 0]));
    const rows = specialization && grade
      ? this.db.prepare('SELECT status, COUNT(*) AS n FROM bank_items WHERE specialization=? AND grade=? GROUP BY status').all(specialization, grade)
      : this.db.prepare('SELECT status, COUNT(*) AS n FROM bank_items GROUP BY status').all();
    for (const row of rows) counts[row.status] = row.n;
    const seed = specialization && grade
      ? this.programs?.[specialization]?.[grade]?.families.reduce((sum, family) => sum + family.variants.length, 0) || 0
      : [...this.families.values()].reduce((sum, family) => sum + family.variants.length, 0);
    return { authored: seed, generated: counts };
  }
}
